import{z as n,x as m,o as A,c as i,q as r,j as t,D as e,d as s,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"文法缓存与复用","description":"","frontmatter":{"title":"文法缓存与复用","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dec-grammar-cache.md","filePath":"llm/dec-grammar-cache.md","lastUpdated":1791413859000}'),d={name:"llm/dec-grammar-cache.md"};function p(C,a,c,h,D,F){const B=m("Mermaid");return A(),i("div",null,[a[2]||(a[2]=r('<h1 id="文法缓存与复用" tabindex="-1">文法缓存与复用 <a class="header-anchor" href="#文法缓存与复用" aria-label="Permalink to &quot;文法缓存与复用&quot;">​</a></h1><div class="epigraph"><p>编译一次是优化，编译千次是事故；缓存键里漏掉分词器，命中越多越危险。</p><footer>—— 据 Dong et al., XGrammar, arXiv:2411.15100 的自适应掩码缓存与 SGLang 缓存工程整理</footer></div><p><a href="/llm/dec-schema-compile">上一课</a>把单个 schema 的编译压到可承受：简化、token 级索引、预计算与运行时切分。服务一天见到的 schema 远不止一个：工具定义、表单、信封各有各的文法，还有长尾被反复请求。本课写缓存与复用：什么做键、存什么、怎么失效、怎么度量。后课的多约束组合把缓存键扩成元组。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缓存的候选有三层。第一层是<strong>编译产物</strong>：FSM / PDA、离线掩码表——不缓存它，每个请求付一次完整编译，冷启动打在 TTFT。第二层是<strong>运行时格局掩码</strong>：PDA 格局到合法 token 集的映射，XGrammar 用自适应缓存记住见过的格局，命中率决定逐步开销接近查表还是回到线性。第三层是与 <strong>KV 前缀缓存</strong>的联动：系统提示加工具定义这段前缀在<a href="/llm/kv-prefix-cache">前缀缓存</a>里照常命中，结构化请求的开销集中在正文分叉之后。三层各有键、容量与失效问题；缺一层，TTFT 或 TPOT 的尾部就会间歇性变差，而平均数看不出来。</p><p><span class="marginnote">术语翻译：「格局」就是自动机当前走到哪一步的快照——状态编号加上栈里压了什么。同一段 JSON 写到 <code>{&quot;name&quot;:&quot;</code> 和写到 <code>{&quot;age&quot;:</code> 是两个不同格局，各自允许的下一批 token 不同；格局缓存就是把「见过的快照 → 允许 token 表」记下来，下次同快照直接查表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>键设计</strong>：编译产物缓存键至少三个字段——归一化后的 schema 哈希、分词器指纹、编译器版本。归一化要消掉空白、转义与键序差（若产品已固定键序则按序哈希）；分词器指纹防「换模型旧表照用」；编译器版本防算法升级后新旧产物混存。格局缓存的键是自动机格局本身（状态加栈），属进程内热数据，不需要跨机共享。</p><p><strong>存储与容量</strong>：编译产物小而贵，放进程级或节点级 LRU，容量按「活跃 schema 数 × 单产物大小」估；格局缓存大而热，放实例内存。多 worker 部署时编译产物可以共享（只读），格局缓存随请求粘性走。</p><p><strong>失效</strong>：三类信号——模型或分词器升级（全量清空编译产物）、schema 演进（哈希变则自然分桶）、引擎升级（版本号进键）。失效错误不是性能问题：给新模型挂旧掩码表，输出仍然合法，但模型已经不是训练时那个条件分布的拥有者。</p><p><span class="marginnote">常见误区：初学者容易以为「schema 文本一样键就一样」，实际上两个请求的 JSON Schema 往往只差空格、转义或键序，直接拿原文做键会让缓存永远 miss。所以键要用归一化后的哈希——先把无意义差异抹平，再哈希，同一模板的不同写法才能命中同一条缓存。</span></p>',11)),(A(),t(l,null,{default:e(()=>[o(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E5%B8%A6%20schema%22%5D%20--%3E%20H%7B%22%E7%BC%96%E8%AF%91%E4%BA%A7%E7%89%A9%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20H%20--%3E%7C%E5%90%A6%7C%20C%5B%22%E7%BC%96%E8%AF%91%E5%B9%B6%E5%85%A5%E5%BA%93%EF%BC%9Aschema%20%E5%93%88%E5%B8%8C%20%C3%97%20%E5%88%86%E8%AF%8D%E5%99%A8%20%C3%97%20%E7%89%88%E6%9C%AC%22%5D%0A%20%20H%20--%3E%7C%E6%98%AF%7C%20GEN%5B%22%E8%BF%9B%E5%85%A5%E8%A7%A3%E7%A0%81%22%5D%0A%20%20C%20--%3E%20GEN%0A%20%20GEN%20--%3E%20S%7B%22%E6%A0%BC%E5%B1%80%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20S%20--%3E%7C%E6%98%AF%7C%20M%5B%22%E6%9F%A5%E8%A1%A8%E5%8F%96%E6%8E%A9%E7%A0%81%22%5D%0A%20%20S%20--%3E%7C%E5%90%A6%7C%20RC%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E8%A1%A5%E7%AE%97%E5%B9%B6%E5%9B%9E%E5%A1%AB%22%5D%0A%20%20RC%20--%3E%20M%0A%20%20M%20--%3E%20STEP%5B%22%E6%9C%AC%E6%AD%A5%E9%87%87%E6%A0%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"缓存有效的理由在上一课已经埋下：真实流量的 schema 集中在少数模板上，PDA 格局集中在键名、标点与常见类型上。两层缓存的命中差体现为不同指标：编译缓存 miss 直接抬高该请求 TTFT（毫秒到百毫秒级，取决于 \\(|Q|\\cdot|\\mathcal{V}|\\)），格局缓存 miss 抬高 TPOT 的单步 CPU 时间。度量要分开报：编译命中率、格局命中率、以及 miss 时回源成本，否则「平均延迟没变」掩盖了长尾。",-1)),a[5]||(a[5]=E("p",null,"与 KV 缓存的复用同构但不同层：文法压缩在无分支路段直接写出确定 token、跳过前向，这些 token 照常写进 KV、照常能被 radix 树共享——结构化流量的系统提示前缀命中率与自由文本无异，分叉从正文第一个自由值开始。",-1)),a[6]||(a[6]=E("p",null,"三层缓存回答的问题不同：键是什么、放在哪、miss 时谁付钱。第一图画的是请求查缓存的流程，这里补一张三层对照：",-1)),(A(),t(l,null,{default:e(()=>[o(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20L1%5B%22%E7%BC%96%E8%AF%91%E4%BA%A7%E7%89%A9%E7%BC%93%E5%AD%98%22%5D%0A%20%20%20%20K1%5B%22%E9%94%AE%EF%BC%9Aschema%20%E5%93%88%E5%B8%8C%20%C3%97%20%E5%88%86%E8%AF%8D%E5%99%A8%20%C3%97%20%E7%89%88%E6%9C%AC%22%5D%20--%3E%20S1%5B%22%E8%BF%9B%E7%A8%8B%2F%E8%8A%82%E7%82%B9%E7%BA%A7%20LRU%22%5D%0A%20%20%20%20S1%20--%3E%20F1%5B%22miss%20%E4%BB%A3%E4%BB%B7%EF%BC%9ATTFT%20%E6%8A%AC%E9%AB%98%E5%87%A0%E5%8D%81%E8%87%B3%E5%87%A0%E7%99%BE%20ms%22%5D%0A%20%20end%0A%20%20subgraph%20L2%5B%22%E6%A0%BC%E5%B1%80%E6%8E%A9%E7%A0%81%E7%BC%93%E5%AD%98%22%5D%0A%20%20%20%20K2%5B%22%E9%94%AE%EF%BC%9A%E7%8A%B6%E6%80%81%20%2B%20%E6%A0%88%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20S2%5B%22%E5%AE%9E%E4%BE%8B%E5%86%85%E5%AD%98%EF%BC%8C%E8%BF%9B%E7%A8%8B%E5%86%85%E7%83%AD%E6%95%B0%E6%8D%AE%22%5D%0A%20%20%20%20S2%20--%3E%20F2%5B%22miss%20%E4%BB%A3%E4%BB%B7%EF%BC%9ATPOT%20%E5%8D%95%E6%AD%A5%20CPU%20%E5%8F%98%E9%95%BF%22%5D%0A%20%20end%0A%20%20subgraph%20L3%5B%22KV%20%E5%89%8D%E7%BC%80%E7%BC%93%E5%AD%98%E8%81%94%E5%8A%A8%22%5D%0A%20%20%20%20K3%5B%22%E9%94%AE%EF%BC%9A%E5%89%8D%E7%BC%80%20token%20%E4%B8%B2%22%5D%20--%3E%20S3%5B%22radix%20%E6%A0%91%E5%85%B1%E4%BA%AB%22%5D%0A%20%20%20%20S3%20--%3E%20F3%5B%22miss%20%E4%BB%A3%E4%BB%B7%EF%BC%9A%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%E6%AE%B5%E9%87%8D%E7%AE%97%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">为什么重要：三层 miss 打中的指标不一样——编译缓存 miss 只坑该请求的首 token 延迟，格局缓存 miss 拖慢每一个后续 token。所以监控必须分层报命中率，只看「平均延迟没变」会把长尾恶化藏几周才发现。</span></p><p><span class="marginnote">数字感受：1000 QPS 下每请求重复编译 50ms 的 schema，等于常驻烧掉 50 个 CPU 核只做重复劳动；命中缓存的同请求成本接近零。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>缓存不改变正确性要求：失效管理的第一原则是「宁可重编译，不可错复用」。编译炸弹在缓存层同样要防：恶意 schema 会先在编译期烧 CPU 与内存，限额与审计在缓存之前。多租户共享编译产物是安全的（schema 不是机密，掩码不泄露数据），但共享格局缓存的键里若有用户自定义词表片段，要按租户隔离。最后，命中率是资产也是负担：schema 长尾越散，缓存的边际价值越低，此时先把 schema 模板收敛，比扩缓存便宜。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三层缓存：编译产物、运行时格局掩码、与 KV 前缀缓存的联动；各管 TTFT、TPOT 与共享段。</li><li>编译缓存键：归一化 schema 哈希 × 分词器指纹 × 编译器版本，缺一即静默事故。</li><li>失效信号三类：模型升级、schema 演进、引擎升级；失效错误的代价是正确性。</li><li>命中率要按层分开报，miss 的回源成本决定长尾。</li><li>防编译炸弹在缓存之前；schema 收敛比扩缓存便宜。</li><li>出处：Dong et al., XGrammar, arXiv:2411.15100；Zheng et al., SGLang, NeurIPS 2024；Willard &amp; Louf, arXiv:2307.09702。</li></ul>',6))])}const g=n(d,[["render",p]]);export{u as __pageData,g as default};
